4	const { Readable } = require('node:stream')
5	const util = require('../core/util')
6	const CacheHandler = require('../handler/cache-handler')
7	const MemoryCacheStore = require('../cache/memory-cache-store')
8	const CacheRevalidationHandler = require('../handler/cache-revalidation-handler')
9	const {
10	  assertCacheStore,
11	  assertCacheMethods,
12	  getInterceptorOrigin,
13	  makeCacheKey,
14	  normalizeHeaders,
15	  parseCacheControlHeader,
16	  isInvalidOrWildcardVaryHeader,
17	  parseVaryHeader
18	} = require('../util/cache.js')
19	const { AbortError } = require('../core/errors.js')
20	const { parseHttpDate } = require('../util/date.js')
