22	/**
23	 * @param {(string | RegExp)[] | undefined} origins
24	 * @param {string} name
25	 */
26	function assertCacheOrigins (origins, name) {
27	  if (origins === undefined) return
28	  if (!Array.isArray(origins)) {
29	    throw new TypeError(`expected ${name} to be an array or undefined, got ${typeof origins}`)
30	  }
31	  for (let i = 0; i < origins.length; i++) {
32	    const origin = origins[i]
33	    if (typeof origin !== 'string' && !(origin instanceof RegExp)) {
34	      throw new TypeError(`expected ${name}[${i}] to be a string or RegExp, got ${typeof origin}`)
35	    }
36	  }
37	}
38	
39	const nop = () => {}
40	
41	function trimOWS (value) {
42	  return value.replace(/^[\t ]+|[\t ]+$/g, '')
43	}
44	
45	function arrayIncludes (array, value) {
46	  for (let i = 0; i < array.length; i++) {
47	    if (array[i] === value) {
48	      return true
49	    }
50	  }
51	
52	  return false
53	}
54	
55	function hasPragmaNoCache (headers) {
56	  const pragma = headers?.pragma
57	  if (!pragma) {
58	    return false
59	  }
60	
61	  const values = Array.isArray(pragma) ? pragma : [pragma]
62	  for (let i = 0; i < values.length; i++) {
63	    const value = values[i]
64	    if (typeof value !== 'string') {
65	      continue
66	    }
67	
68	    const directives = value.split(',')
69	    for (let j = 0; j < directives.length; j++) {
70	      if (trimOWS(directives[j]).toLowerCase() === 'no-cache') {
71	        return true
72	      }
73	    }
74	  }
75	
76	  return false
77	}
78	
79	/**
80	 * @typedef {(options: import('../../types/dispatcher.d.ts').default.DispatchOptions, handler: import('../../types/dispatcher.d.ts').default.DispatchHandler) => void} DispatchFn
81	 */
82	
83	/**
84	 * @param {import('../../types/cache-interceptor.d.ts').default.GetResult} result
85	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheControlDirectives | undefined} cacheControlDirectives
86	 * @param {import('../../types/dispatcher.d.ts').default.RequestOptions} opts
87	 * @returns {boolean}
88	 */
89	function needsRevalidation (result, cacheControlDirectives, { headers = {} }) {
90	  // Always revalidate requests with the no-cache request directive.
91	  if (cacheControlDirectives?.['no-cache']) {
92	    return true
93	  }
94	
95	  // Always revalidate requests with unqualified no-cache response directive.
96	  if (result.cacheControlDirectives?.['no-cache'] && !Array.isArray(result.cacheControlDirectives['no-cache'])) {
97	    return true
98	  }
99	
100	  // Always revalidate requests with conditional headers.
101	  if (headers['if-modified-since'] || headers['if-none-match']) {
102	    return true
103	  }
104	
105	  return false
106	}
107	
108	/**
109	 * @param {import('../../types/cache-interceptor.d.ts').default.GetResult} result
110	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheOptions['type']} cacheType
111	 * @returns {boolean}
112	 */
113	function staleResponseRequiresRevalidation (result, cacheType) {
114	  return result.cacheControlDirectives?.['must-revalidate'] === true ||
115	    (cacheType === 'shared' && (
116	      result.cacheControlDirectives?.['proxy-revalidate'] === true ||
117	      // https://www.rfc-editor.org/rfc/rfc9111.html#section-5.2.2.10
118	      // s-maxage implies proxy-revalidate for shared caches.
119	      result.cacheControlDirectives?.['s-maxage'] !== undefined
120	    ))
121	}
122	
123	/**
124	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheOptions['type']} cacheType
125	 * @param {import('../../types/header.d.ts').IncomingHttpHeaders} headers
126	 * @returns {boolean}
127	 */
128	function revalidationResponseDisallowsCachedReuse (cacheType, headers) {
129	  if (headers.vary && isInvalidOrWildcardVaryHeader(headers.vary)) {
130	    return true
131	  }
132	
133	  const cacheControl = headers['cache-control']
134	  if (!cacheControl) {
135	    return false
136	  }
137	
138	  const cacheControlDirectives = parseCacheControlHeader(cacheControl)
139	  return cacheControlDirectives['no-store'] === true ||
140	    (cacheType === 'shared' && cacheControlDirectives.private === true)
141	}
142	
143	function revalidationResponseUpdatesCacheControl (headers) {
144	  return headers['cache-control'] !== undefined
145	}
146	
147	/**
148	 * @param {import('../../types/cache-interceptor.d.ts').default.GetResult} result
149	 * @param {Record<string, string | string[] | null> | undefined} varyDirectives
150	 * @returns {boolean}
151	 */
152	function revalidationResponseAddsVary (result, varyDirectives) {
153	  if (!varyDirectives) {
154	    return false
155	  }
156	
157	  for (const key in varyDirectives) {
158	    if (result.vary == null || !Object.hasOwn(result.vary, key)) {
159	      return true
160	    }
161	  }
162	
163	  return false
164	}
165	
166	function deleteCachedValue (store, cacheKey) {
167	  try {
168	    store.delete(cacheKey)?.catch?.(nop)
169	  } catch {
170	    // Fail silently
171	  }
172	}
173	
174	function getUsableLastModified (headers) {
175	  const lastModified = headers?.['last-modified']
176	  if (typeof lastModified === 'string' && parseHttpDate(lastModified)) {
177	    return lastModified
178	  }
179	}
180	
181	function makeRevalidationHeaders (opts, result) {
182	  const headers = {
183	    ...opts.headers,
184	    'if-modified-since': getUsableLastModified(result.headers) ?? new Date(result.cachedAt).toUTCString()
185	  }
186	
187	  if (result.etag) {
188	    headers['if-none-match'] = result.etag
189	  }
190	
191	  if (result.vary) {
192	    for (const key in result.vary) {
193	      if (result.vary[key] != null) {
194	        headers[key] = result.vary[key]
195	      }
196	    }
197	  }
198	
199	  return headers
200	}
201	
202	/**
203	 * @param {import('../../types/cache-interceptor.d.ts').default.GetResult} result
204	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheControlDirectives | undefined} cacheControlDirectives
205	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheOptions['type']} cacheType
206	 * @returns {boolean}
207	 */
208	function isStale (result, cacheControlDirectives, cacheType) {
209	  const now = Date.now()
210	  if (now > result.staleAt) {
211	    // Response is stale
212	    if (!staleResponseRequiresRevalidation(result, cacheType) && cacheControlDirectives?.['max-stale']) {
213	      // There's a threshold where we can serve stale responses, let's see if
214	      //  we're in it
215	      // https://www.rfc-editor.org/rfc/rfc9111.html#name-max-stale
216	      const gracePeriod = result.staleAt + (cacheControlDirectives['max-stale'] * 1000)
217	      return now > gracePeriod
218	    }
219	
220	    return true
221	  }
222	
223	  if (cacheControlDirectives?.['min-fresh']) {
224	    // https://www.rfc-editor.org/rfc/rfc9111.html#section-5.2.1.3
225	
226	    // At this point, staleAt is always > now
227	    const timeLeftTillStale = result.staleAt - now
228	    const threshold = cacheControlDirectives['min-fresh'] * 1000
229	
230	    return timeLeftTillStale <= threshold
231	  }
232	
233	  return false
234	}
235	
236	/**
237	 * Check if we're within the stale-while-revalidate window for a stale response
238	 * @param {import('../../types/cache-interceptor.d.ts').default.GetResult} result
239	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheOptions['type']} cacheType
240	 * @returns {boolean}
241	 */
242	function withinStaleWhileRevalidateWindow (result, cacheType) {
243	  const staleWhileRevalidate = result.cacheControlDirectives?.['stale-while-revalidate']
244	  if (!staleWhileRevalidate || staleResponseRequiresRevalidation(result, cacheType)) {
245	    return false
246	  }
247	
248	  const now = Date.now()
249	  const staleWhileRevalidateExpiry = result.staleAt + (staleWhileRevalidate * 1000)
250	  return now <= staleWhileRevalidateExpiry
251	}
252	
253	/**
254	 * @param {DispatchFn} dispatch
255	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheHandlerOptions} globalOpts
256	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheKey} cacheKey
257	 * @param {import('../../types/dispatcher.d.ts').default.DispatchHandler} handler
258	 * @param {import('../../types/dispatcher.d.ts').default.RequestOptions} opts
259	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheControlDirectives | undefined} reqCacheControl
260	 */
261	function handleUncachedResponse (
262	  dispatch,
263	  globalOpts,
264	  cacheKey,
265	  handler,
266	  opts,
267	  reqCacheControl
268	) {
269	  if (reqCacheControl?.['only-if-cached']) {
270	    let aborted = false
271	
272	    const controller = {
273	      paused: false,
274	      rawHeaders: [],
275	      rawTrailers: [],
276	      pause () {
277	        this.paused = true
278	      },
279	      resume () {
280	        this.paused = false
281	      },
282	      abort: (reason) => {
283	        aborted = true
284	        handler.onResponseError?.(controller, reason ?? new AbortError())
285	      }
286	    }
287	
288	    try {
289	      handler.onRequestStart?.(controller, null)
290	
291	      if (aborted) {
292	        return
293	      }
294	
295	      handler.onResponseStart?.(controller, 504, {}, 'Gateway Timeout')
296	      if (aborted) {
297	        return
298	      }
299	
300	      handler.onResponseEnd?.(controller, {})
301	    } catch (err) {
302	      if (typeof handler.onResponseError === 'function') {
303	        handler.onResponseError(controller, err)
304	      }
305	    }
306	
307	    return true
308	  }
309	
310	  return dispatch(opts, new CacheHandler(globalOpts, cacheKey, handler))
311	}
312	
313	/**
314	 * @param {import('../../types/dispatcher.d.ts').default.DispatchHandler} handler
315	 * @param {import('../../types/dispatcher.d.ts').default.RequestOptions} opts
316	 * @param {import('../../types/cache-interceptor.d.ts').default.GetResult} result
317	 * @param {number} age
318	 * @param {any} context
319	 * @param {boolean} isStale
320	 */
321	function sendCachedValue (handler, opts, result, age, context, isStale) {
322	  // TODO (perf): Readable.from path can be optimized...
323	  const stream = util.isStream(result.body)
324	    ? result.body
325	    : Readable.from(result.body ?? [])
326	
327	  assert(!stream.destroyed, 'stream should not be destroyed')
328	  assert(!stream.readableDidRead, 'stream should not be readableDidRead')
329	
330	  const controller = {
331	    rawHeaders: [],
332	    rawTrailers: [],
333	    resume () {
334	      stream.resume()
335	    },
336	    pause () {
337	      stream.pause()
338	    },
339	    get paused () {
340	      return stream.isPaused()
341	    },
342	    get aborted () {
343	      return stream.destroyed
344	    },
345	    get reason () {
346	      return stream.errored
347	    },
348	    abort (reason) {
349	      stream.destroy(reason ?? new AbortError())
350	    }
351	  }
352	
353	  stream
354	    .on('error', function (err) {
355	      if (!this.readableEnded) {
356	        if (typeof handler.onResponseError === 'function') {
357	          handler.onResponseError(controller, err)
358	        } else {
359	          throw err
360	        }
361	      }
362	    })
363	    .on('close', function () {
364	      if (!this.errored) {
365	        handler.onResponseEnd?.(controller, {})
366	      }
367	    })
368	
369	  handler.onRequestStart?.(controller, context)
370	
371	  if (stream.destroyed) {
372	    return
373	  }
374	
375	  // Add the age header
376	  // https://www.rfc-editor.org/rfc/rfc9111.html#name-age
377	  const headers = { ...result.headers, age: String(age) }
378	
379	  if (isStale) {
380	    // Add warning header
381	    //  https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Warning
382	    headers.warning = '110 - "response is stale"'
383	  }
384	
385	  controller.rawHeaders = util.toRawHeaders(headers)
386	
387	  handler.onResponseStart?.(controller, result.statusCode, headers, result.statusMessage)
388	
389	  if (opts.method === 'HEAD') {
390	    stream.destroy()
391	  } else {
392	    stream.on('data', function (chunk) {
393	      handler.onResponseData?.(controller, chunk)
394	    })
395	  }
396	}
397	
398	/**
399	 * @param {DispatchFn} dispatch
400	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheHandlerOptions} globalOpts
401	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheKey} cacheKey
402	 * @param {import('../../types/dispatcher.d.ts').default.DispatchHandler} handler
403	 * @param {import('../../types/dispatcher.d.ts').default.RequestOptions} opts
404	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheControlDirectives | undefined} reqCacheControl
405	 * @param {import('../../types/cache-interceptor.d.ts').default.GetResult | undefined} result
406	 */
407	function handleResult (
408	  dispatch,
409	  globalOpts,
410	  cacheKey,
411	  handler,
412	  opts,
413	  reqCacheControl,
414	  result
415	) {
416	  if (!result) {
417	    return handleUncachedResponse(dispatch, globalOpts, cacheKey, handler, opts, reqCacheControl)
418	  }
419	
420	  const now = Date.now()
421	  if (now > result.deleteAt) {
422	    // Response is expired, cache store shouldn't have given this to us
423	    return dispatch(opts, new CacheHandler(globalOpts, cacheKey, handler))
424	  }
425	
426	  const age = Math.round((now - result.cachedAt) / 1000)
427	  const requestMaxAgeExpired = reqCacheControl?.['max-age'] !== undefined && age >= reqCacheControl['max-age']
428	
429	  const stale = requestMaxAgeExpired || isStale(result, reqCacheControl, globalOpts.type)
430	  const revalidate = requestMaxAgeExpired || needsRevalidation(result, reqCacheControl, opts)
431	
432	  // Check if the response is stale
433	  if (stale || revalidate) {
434	    if (util.isStream(opts.body) && util.bodyLength(opts.body) !== 0) {
435	      // If body is a stream we can't revalidate...
436	      // TODO (fix): This could be less strict...
437	      return dispatch(opts, new CacheHandler(globalOpts, cacheKey, handler))
438	    }
439	
440	    // RFC 5861: If we're within stale-while-revalidate window, serve stale immediately
441	    // and revalidate in background, unless immediate revalidation is necessary
442	    if (!revalidate && withinStaleWhileRevalidateWindow(result, globalOpts.type)) {
443	      // Serve stale response immediately
444	      sendCachedValue(handler, opts, result, age, null, true)
445	
446	      // Start background revalidation (fire-and-forget)
447	      queueMicrotask(() => {
448	        const headers = makeRevalidationHeaders(opts, result)
449	
450	        // Background revalidation - update cache if we get new data
451	        dispatch(
452	          {
453	            ...opts,
454	            headers
455	          },
456	          new CacheHandler(globalOpts, cacheKey, {
457	            // Silent handler that just updates the cache
458	            onRequestStart () {},
459	            onRequestUpgrade () {},
460	            onResponseStart () {},
461	            onResponseData () {},
462	            onResponseEnd () {},
463	            onResponseError () {}
464	          })
465	        )
466	      })
467	
468	      return true
469	    }
470	
471	    let withinStaleIfErrorThreshold = false
472	    if (!staleResponseRequiresRevalidation(result, globalOpts.type)) {
473	      const staleIfErrorExpiry = result.cacheControlDirectives['stale-if-error'] ?? reqCacheControl?.['stale-if-error']
474	      if (staleIfErrorExpiry) {
475	        withinStaleIfErrorThreshold = now < (result.staleAt + (staleIfErrorExpiry * 1000))
476	      }
477	    }
478	
479	    const headers = makeRevalidationHeaders(opts, result)
480	
481	    // We need to revalidate the response
482	    return dispatch(
483	      {
484	        ...opts,
485	        headers
486	      },
487	      new CacheRevalidationHandler(
488	        (success, context, statusCode, headers) => {
489	          if (success) {
490	            if (statusCode === 304) {
491	              if (revalidationResponseDisallowsCachedReuse(globalOpts.type, headers)) {
492	                if (util.isStream(result.body)) {
493	                  result.body.on('error', nop).destroy()
494	                }
495	
496	                deleteCachedValue(globalOpts.store, cacheKey)
497	                return dispatch(opts, new CacheHandler(globalOpts, cacheKey, handler))
498	              }
499	
500	              if (revalidationResponseUpdatesCacheControl(headers)) {
501	                deleteCachedValue(globalOpts.store, cacheKey)
502	              } else if (revalidationResponseAddsVary(result, headers.vary ? parseVaryHeader(headers.vary, opts.headers) : undefined)) {
503	                if (util.isStream(result.body)) {
504	                  result.body.on('error', nop).destroy()
505	                }
506	
507	                deleteCachedValue(globalOpts.store, cacheKey)
508	                return dispatch(opts, new CacheHandler(globalOpts, cacheKey, handler))
509	              }
510	            }
511	
512	            // TODO: successful revalidation should be considered fresh (not give stale warning).
513	            sendCachedValue(handler, opts, result, age, context, stale)
514	          } else if (util.isStream(result.body)) {
515	            result.body.on('error', nop).destroy()
516	          }
517	        },
518	        new CacheHandler(globalOpts, cacheKey, handler),
519	        withinStaleIfErrorThreshold
520	      )
521	    )
522	  }
523	
524	  // Dump request body.
525	  if (util.isStream(opts.body)) {
526	    opts.body.on('error', nop).destroy()
527	  }
528	
529	  sendCachedValue(handler, opts, result, age, null, false)
530	}
531	
532	/**
533	 * @param {import('../../types/cache-interceptor.d.ts').default.CacheOptions} [opts]
534	 * @returns {import('../../types/dispatcher.d.ts').default.DispatcherComposeInterceptor}
535	 */
536	module.exports = (opts = {}) => {
537	  const {
538	    store = new MemoryCacheStore(),
539	    methods = ['GET'],
540	    cacheByDefault = undefined,
541	    type = 'shared',
542	    origins = undefined
543	  } = opts
544	
545	  if (typeof opts !== 'object' || opts === null) {
546	    throw new TypeError(`expected type of opts to be an Object, got ${opts === null ? 'null' : typeof opts}`)
547	  }
548	
549	  assertCacheStore(store, 'opts.store')
550	  assertCacheMethods(methods, 'opts.methods')
551	  assertCacheOrigins(origins, 'opts.origins')
552	
553	  if (typeof cacheByDefault !== 'undefined' && typeof cacheByDefault !== 'number') {
554	    throw new TypeError(`expected opts.cacheByDefault to be number or undefined, got ${typeof cacheByDefault}`)
555	  }
556	
557	  if (typeof type !== 'undefined' && type !== 'shared' && type !== 'private') {
558	    throw new TypeError(`expected opts.type to be shared, private, or undefined, got ${typeof type}`)
559	  }
560	
561	  const globalOpts = {
562	    store,
563	    methods,
564	    cacheByDefault,
565	    type
566	  }
567	
568	  const safeMethodsToNotCache = []
569	  for (let i = 0; i < util.safeHTTPMethods.length; i++) {
570	    const method = util.safeHTTPMethods[i]
571	    if (!arrayIncludes(methods, method)) {
572	      safeMethodsToNotCache.push(method)
573	    }
574	  }
575	
576	  return (dispatch, interceptorOrigin) => {
577	    return (opts, handler) => {
578	      const requestOrigin = getInterceptorOrigin(opts, interceptorOrigin)
579	      if (!requestOrigin || arrayIncludes(safeMethodsToNotCache, opts.method)) {
580	        // We cannot safely cache without an authoritative origin, or this is
581	        // not a method we want to cache.
582	        return dispatch(opts, handler)
583	      }
584	
585	      // Check if origin is in whitelist
586	      if (origins !== undefined) {
587	        const normalizedRequestOrigin = requestOrigin.toString().toLowerCase()
588	        let isAllowed = false
589	
590	        for (let i = 0; i < origins.length; i++) {
591	          const allowed = origins[i]
592	          if (typeof allowed === 'string') {
593	            if (allowed.toLowerCase() === normalizedRequestOrigin) {
594	              isAllowed = true
595	              break
596	            }
597	          } else if (allowed.test(normalizedRequestOrigin)) {
598	            isAllowed = true
599	            break
600	          }
601	        }
602	
603	        if (!isAllowed) {
604	          return dispatch(opts, handler)
605	        }
606	      }
607	
608	      opts = {
609	        ...opts,
610	        headers: normalizeHeaders(opts)
611	      }
612	
613	      const reqCacheControl = opts.headers?.['cache-control']
614	        ? parseCacheControlHeader(opts.headers['cache-control'])
615	        : hasPragmaNoCache(opts.headers)
616	          ? { 'no-cache': true }
617	          : undefined
618	
619	      if (reqCacheControl?.['no-store']) {
620	        return dispatch(opts, handler)
621	      }
622	
623	      /**
624	       * @type {import('../../types/cache-interceptor.d.ts').default.CacheKey}
625	       */
626	      const cacheKey = makeCacheKey(opts, requestOrigin)
627	
628	      if (!arrayIncludes(util.safeHTTPMethods, opts.method)) {
629	        return dispatch(opts, new CacheHandler(globalOpts, cacheKey, handler))
630	      }
631	
632	      const result = store.get(cacheKey)
633	
634	      if (result && typeof result.then === 'function') {
635	        return result
636	          .then(result => handleResult(dispatch,
637	            globalOpts,
638	            cacheKey,
639	            handler,
640	            opts,
641	            reqCacheControl,
642	            result
643	          ))
644	      } else {
645	        return handleResult(
646	          dispatch,
647	          globalOpts,
648	          cacheKey,
649	          handler,
650	          opts,
651	          reqCacheControl,
652	          result
653	        )
654	      }
655	    }
656	  }
657	}
