'use strict'

const { createServer } = require('node:http')
const { once } = require('node:events')
const assert = require('node:assert')
const { Client, interceptors, cacheStores } = require('./index.js')

async function testStore (type, expectSecondFromCache) {
  let requestsToOrigin = 0
  const server = createServer({ joinDuplicateHeaders: true }, (_, res) => {
    requestsToOrigin++
    res.setHeader('cache-control', 'public, max-age=60')
    res.setHeader('set-cookie', `session=secret-${requestsToOrigin}`)
    res.end('ok')
  }).listen(0)
  await once(server, 'listening')

  const client = new Client(`http://localhost:${server.address().port}`)
    .compose(interceptors.cache({ type }))

  const req = { origin: 'localhost', method: 'GET', path: '/' }
  const a = await client.request(req)
  assert.strictEqual(await a.body.text(), 'ok')
  assert.strictEqual(a.headers['set-cookie'], 'session=secret-1')

  const b = await client.request(req)
  await b.body.text()
  assert.strictEqual(requestsToOrigin, expectSecondFromCache ? 1 : 2, `${type}: origin hits`)
  if (expectSecondFromCache) {
    assert.strictEqual(b.headers['set-cookie'], 'session=secret-1', `${type}: cookie replayed`)
  } else {
    assert.strictEqual(b.headers['set-cookie'], 'session=secret-2', `${type}: fresh cookie`)
  }

  await client.close()
  await new Promise(resolve => server.close(resolve))
  console.log(`ok: type=${type} storing (origin hits=${requestsToOrigin})`)
}

// An entry already in the store (e.g. written by an older version) must not be served.
async function testExistingEntry () {
  let requestsToOrigin = 0
  const server = createServer({ joinDuplicateHeaders: true }, (_, res) => {
    requestsToOrigin++
    res.setHeader('cache-control', 'public, max-age=60')
    res.end('fresh')
  }).listen(0)
  await once(server, 'listening')

  const store = new cacheStores.MemoryCacheStore()
  const key = { origin: 'http://localhost', method: 'GET', path: '/' }
  const now = Date.now()
  const stream = store.createWriteStream(key, {
    statusCode: 200,
    statusMessage: 'OK',
    headers: { 'cache-control': 'public, max-age=60', 'set-cookie': 'session=stale-secret' },
    cacheControlDirectives: { public: true, 'max-age': 60 },
    cachedAt: now,
    staleAt: now + 60_000,
    deleteAt: now + 120_000
  })
  stream.end('stale')

  const client = new Client(`http://localhost:${server.address().port}`)
    .compose(interceptors.cache({ store }))

  const res = await client.request({ origin: 'localhost', method: 'GET', path: '/' })
  assert.strictEqual(res.headers['set-cookie'], undefined, 'existing entry cookie served')
  assert.strictEqual(await res.body.text(), 'fresh')
  assert.strictEqual(requestsToOrigin, 1)
  assert.strictEqual(store.get(key)?.headers?.['set-cookie'], undefined, 'entry kept')

  await client.close()
  await new Promise(resolve => server.close(resolve))
  console.log('ok: pre-existing entry with set-cookie is dropped')
}

// A 304 that carries a Set-Cookie must not be merged into the stored entry.
async function testRevalidation () {
  let requestsToOrigin = 0
  const server = createServer({ joinDuplicateHeaders: true }, (req, res) => {
    requestsToOrigin++
    if (req.headers['if-none-match'] === '"asd"' && requestsToOrigin === 2) {
      res.setHeader('cache-control', 'public, max-age=1')
      res.setHeader('etag', '"asd"')
      res.setHeader('set-cookie', 'session=secret-on-304')
      res.statusCode = 304
      res.end()
      return
    }
    res.setHeader('cache-control', 'public, max-age=1')
    res.setHeader('etag', '"asd"')
    res.end(`body-${requestsToOrigin}`)
  }).listen(0)
  await once(server, 'listening')

  const client = new Client(`http://localhost:${server.address().port}`)
    .compose(interceptors.cache())

  const req = { origin: 'localhost', method: 'GET', path: '/' }
  assert.strictEqual(await (await client.request(req)).body.text(), 'body-1')
  await new Promise(resolve => setTimeout(resolve, 1500))

  const b = await client.request(req)
  const body = await b.body.text()
  assert.strictEqual(b.headers['set-cookie'], undefined, '304 cookie leaked')
  assert.strictEqual(body, 'body-3', `refetched instead of reusing, got ${body}`)

  // The entry must not be re-served with the cookie either.
  const c = await client.request(req)
  assert.strictEqual(c.headers['set-cookie'], undefined, 'cookie leaked on later read')
  await c.body.text()

  await client.close()
  await new Promise(resolve => server.close(resolve))
  console.log(`ok: 304 with set-cookie not reused (origin hits=${requestsToOrigin})`)
}

async function main () {
  await testStore('shared', false)
  await testStore('private', true)
  await testExistingEntry()
  await testRevalidation()
}

main()

