      strictEqual(await res.body.text(), 'asd')
      strictEqual(requestsToOrigin, 1)
      strictEqual(revalidationRequests, 1)
    }
  })

  test('expires caching', async () => {
    const clock = FakeTimers.install({
      toFake: ['Date']
    })

